<?php
declare(strict_types=1);

// One authoritative calculation path for preview, draft saves and approvals.
function fc_today():string{return (new DateTimeImmutable('now',new DateTimeZone('Africa/Windhoek')))->format('Y-m-d');}
function fc_find(array $rows,string $key,$id):?array{foreach($rows as $r)if((string)($r[$key]??'')===(string)$id)return $r;return null;}
function fc_number($v,bool $positive=false):float{if(!is_numeric($v)||!is_finite((float)$v)||(float)$v<0||($positive&&(float)$v<=0))throw new DomainException('Enter a valid '.($positive?'positive':'non-negative').' amount.');return (float)$v;}
function fc_unit(string $u):array{$map=['g'=>['weight',.001,'kg'],'kg'=>['weight',1,'kg'],'ml'=>['volume',.001,'L'],'L'=>['volume',1,'L'],'each'=>['count',1,'each'],'unit'=>['count',1,'each']];if(!isset($map[$u]))throw new DomainException('Unit Conversion Required');return $map[$u];}
function fc_convert($q,string $from,string $to,$density=null):float{
    $a=fc_unit($from);$b=fc_unit($to);$q=fc_number($q)*$a[1];
    if($a[0]!==$b[0]){if(!in_array($a[0],['weight','volume'],true)||!in_array($b[0],['weight','volume'],true)||!is_numeric($density)||(float)$density<=0)throw new DomainException('Unit Conversion Required — enter density in kg/L.');$q=$a[0]==='volume'?$q*(float)$density:$q/(float)$density;}
    return $q/$b[1];
}
function fc_sources(PDO $pdo,array $body=[]):array{
    $date=(string)($body['header']['effective_date']??fc_today());if(!$date||$date>fc_today())$date=fc_today();
    $q=$pdo->prepare("SELECT p.id product_id,p.product_name,p.short_code,p.product_category,p.costing_basis,p.base_unit,c.id landed_cost_id,c.landed_cost_per_base,c.cost_date,c.status_key landed_status,s.supplier_name,COALESCE(i.invoice_number,s.manual_reference,'') supplier_reference FROM cw_cost_products p LEFT JOIN cw_landed_product_costs c ON c.id=(SELECT c2.id FROM cw_landed_product_costs c2 JOIN cw_cost_product_sources s2 ON s2.id=c2.product_source_id LEFT JOIN cw_supplier_invoice_lines l ON l.id=s2.supplier_invoice_line_id LEFT JOIN cw_supplier_invoices i2 ON i2.id=l.supplier_invoice_id WHERE c2.product_id=p.id AND s2.active=1 AND (l.id IS NULL OR (l.active=1 AND i2.approval_status='approved')) AND c2.id=(SELECT x.id FROM cw_landed_product_costs x WHERE x.product_source_id=c2.product_source_id ORDER BY x.calculation_version DESC,x.id DESC LIMIT 1) AND c2.cost_date<=? ORDER BY c2.cost_date DESC,c2.id DESC LIMIT 1) LEFT JOIN cw_cost_product_sources s ON s.id=c.product_source_id LEFT JOIN cw_supplier_invoice_lines il ON il.id=s.supplier_invoice_line_id LEFT JOIN cw_supplier_invoices i ON i.id=il.supplier_invoice_id WHERE p.active=1 ORDER BY p.product_name");$q->execute([$date]);$products=$q->fetchAll();
    // Explicit historical sources are re-read from the ledger, never trusted from client JSON.
    foreach($body['ingredients']??[] as $r){if(empty($r['landed_cost_id']))continue;$q=$pdo->prepare("SELECT p.id product_id,p.product_name,p.short_code,p.product_category,c.costing_basis,c.base_unit,c.id landed_cost_id,c.landed_cost_per_base,c.cost_date,c.status_key landed_status,s.supplier_name,COALESCE(s.manual_reference,'') supplier_reference FROM cw_landed_product_costs c JOIN cw_cost_products p ON p.id=c.product_id JOIN cw_cost_product_sources s ON s.id=c.product_source_id WHERE c.id=? AND c.product_id=? AND c.cost_date<=?");$q->execute([(int)$r['landed_cost_id'],(int)$r['product_id'],$date]);if($old=$q->fetch())$products[]=$old;}
    $settings=[];foreach($pdo->query("SELECT setting_key,setting_value FROM cw_settings WHERE setting_key LIKE 'formulation_%'")->fetchAll()as$r)$settings[$r['setting_key']]=$r['setting_value'];
    return ['products'=>$products,'sizes'=>$pdo->query('SELECT * FROM cw_size_conversions WHERE active=1 ORDER BY measurement_type,base_value')->fetchAll(),'setups'=>cw_packaging_current_setups($pdo,$date),'settings'=>$settings];
}
function fc_setup_applies(array $s,array $h,int $size):bool{return (int)$s['size_conversion_id']===$size&&($s['scope_type']==='default'||($s['scope_type']==='category'&&(string)$s['scope_reference']===(string)($h['category']??''))||($s['scope_type']==='product'&&!empty($h['product_id'])&&(string)$s['scope_reference']===(string)$h['product_id']));}
function fc_calculate(array $b,array $s):array{
    $h=$b['header']??[];$issues=[];$ingredients=[];$sum=0.;$pct=0.;$batch=null;$yield=null;$basis='';$unit='';$allValid=true;
    try{$batch=fc_number($h['reference_batch_size']??null,true);$bu=fc_unit((string)($h['reference_batch_unit']??''));$yu=fc_unit((string)($h['yield_unit']??''));$basis=$yu[0];$unit=$yu[2];if($bu[0]!==$basis)throw new DomainException('Batch and yield must use compatible units.');if(($h['formulation_type']??'')!=='mixed'&&($h['formulation_type']??'')!==$basis)throw new DomainException('Calculation basis must match the finished yield.');$loss=fc_number($h['loss_percent']??0);if($loss>=100)throw new DomainException('Loss must be below 100%.');$yield=fc_number($h['expected_yield']??null,true)*$yu[1];if(($h['yield_mode']??'pre_loss')==='pre_loss')$yield*=1-$loss/100;elseif(($h['yield_mode']??'')!=='final')throw new DomainException('Choose the yield interpretation.');}catch(DomainException $e){$issues[]=$e->getMessage();}
    if(!in_array($h['business_type']??'',['Base Formulation','Finished Product'],true))$issues[]='Select Base Formulation or Finished Product.';
    if(!trim((string)($h['category']??'')))$issues[]='Category is required.';
    if(!in_array($h['mode_key']??'',['quantity','percentage'],true))$issues[]='Choose quantity or percentage entry.';
    foreach($b['ingredients']??[] as $i=>$r){
        $item=null;foreach($s['products'] as $p)if((int)$p['product_id']===(int)($r['product_id']??0)&& (empty($r['landed_cost_id'])||(int)$p['landed_cost_id']===(int)$r['landed_cost_id'])){$item=$p;break;}
        $r['cost']=null;$r['base_quantity']=null;$r['issue']='';
        try{if(!$item)throw new DomainException('Select a Cost Workbook ingredient.');$r['source']=$item;$r['landed_cost_id']=$item['landed_cost_id'];if(($h['mode_key']??'quantity')==='percentage'){$percent=fc_number($r['percentage']??null);$pct+=$percent;if($batch===null)throw new DomainException('Complete batch settings.');$r['quantity']=fc_convert($batch*$percent/100,(string)$h['reference_batch_unit'],(string)($r['unit']??''),$r['density']??null);}else{$r['quantity']=fc_number($r['quantity']??null,true);try{$r['percentage']=$batch?fc_convert($r['quantity'],(string)$r['unit'],(string)$h['reference_batch_unit'],$r['density']??null)/$batch*100:null;}catch(DomainException $e){$r['percentage']=null;}$pct+=(float)($r['percentage']??0);}
            if($r['quantity']<=0)throw new DomainException('Ingredient quantity must be positive.');$r['base_quantity']=fc_convert($r['quantity'],(string)$r['unit'],(string)($item['base_unit']??''),$r['density']??null);
            if(($item['landed_status']??'')!=='complete'||!is_numeric($item['landed_cost_per_base']??null))throw new DomainException('Costing Required');$r['cost']=$r['base_quantity']*(float)$item['landed_cost_per_base'];$sum+=$r['cost'];
        }catch(DomainException $e){$r['issue']=$e->getMessage();$issues[]='Ingredient '.($i+1).': '.$e->getMessage();$allValid=false;}$ingredients[]=$r;
    }
    if(!$ingredients){$issues[]='Add at least one ingredient.';$allValid=false;}
    if(($h['mode_key']??'')==='percentage'&&abs($pct-100)>.01){$issues[]='Ingredient percentages must total 100%.';$allValid=false;}
    if(($h['mode_key']??'')==='quantity'&&($h['formulation_type']??'')!=='mixed'&&abs($pct-100)>.01){$issues[]='Ingredient quantities must reconcile to the reference batch size.';$allValid=false;}
    $fixed=0.;$variable=0.;$overhead=0.;$p=$b['production']??[];
    foreach(['labour','utilities','consumables','quality','other'] as $key){try{$v=fc_number($p[$key]??0);if(($p[$key.'_scaling']??'fixed')==='variable')$variable+=$v;else $fixed+=$v;}catch(DomainException $e){$issues[]='Production '.$key.': '.$e->getMessage();$allValid=false;}}
    try{$overhead=fc_number($p['variable_overhead_percent']??0);}catch(DomainException $e){$issues[]='Invalid overhead.';$allValid=false;}
    $ingredientCost=$allValid?$sum:null;$production=$allValid?$fixed+$variable+$sum*$overhead/100:null;$total=$ingredientCost!==null?$ingredientCost+$production:null;$per=$total!==null&&$yield>0?$total/$yield:null;
    $totals=['ingredient_cost'=>$ingredientCost,'production_cost'=>$production,'total_batch_cost'=>$total,'usable_yield'=>$yield,'base_unit'=>$unit,'basis'=>$basis,'cost_per_yield_unit'=>$per,'percentage_total'=>$pct,'fixed_cost'=>$fixed,'variable_cost'=>$variable,'overhead_percent'=>$overhead];
    $batches=[];foreach($b['batches']??[] as $i=>$r){$r['total']=null;$r['unit_cost']=null;try{$scale=fc_number($r['size']??null,true)/fc_number($h['reference_batch_size']??null,true);if($total!==null&&$yield>0){$r['total']=$sum*$scale+$fixed+$variable*$scale+$sum*$scale*$overhead/100;$r['unit_cost']=$r['total']/($yield*$scale);}}catch(DomainException $e){$issues[]='Scenario '.($i+1).': '.$e->getMessage();}$batches[]=$r;}
    $vat=(float)($s['settings']['formulation_vat_rate']??15);$round=(float)($s['settings']['formulation_rounding_rule']??.5);if($vat<0||$vat>100||$round<=0){$issues[]='Invalid configured VAT or rounding rule.';$vat=15;$round=.5;}
    $sizes=[];foreach($b['selling_sizes']??[] as $i=>$r){foreach(['product_cost','packaging_cost','full_cost','price_ex','price_inc','actual_margin','actual_markup','units_per_batch']as$k)$r[$k]=null;$r['issue']='';try{
        $size=fc_find($s['sizes'],'id',$r['size_id']??0);if(!$size||$size['measurement_type']!==$basis||(float)$size['base_value']<=0)throw new DomainException('Choose a compatible selling size.');
        $matches=array_values(array_filter($s['setups'],function($x)use($h,$size){return fc_setup_applies($x,$h,(int)$size['id']);}));usort($matches,function($a,$b){$rank=['product'=>0,'category'=>1,'default'=>2];return $rank[$a['scope_type']]<=>$rank[$b['scope_type']];});
        $setup=!empty($r['setup_id'])?fc_find($matches,'id',$r['setup_id']):($matches[0]??null);$r['suggested_setup_id']=$setup['id']??null;if(!$setup||empty($setup['complete']))throw new DomainException('Packaging Costing Required');if(empty($r['packaging_confirmed']))throw new DomainException('Confirm the suggested packaging setup.');if($per===null)throw new DomainException('Complete formulation costing first.');
        $r['setup_id']=$setup['id'];$r['size_snapshot']=$size;$r['packaging_snapshot']=$setup;$r['product_cost']=$per*(float)$size['base_value'];$r['packaging_cost']=(float)$setup['cost_ex_vat'];$full=$r['product_cost']+$r['packaging_cost'];$r['full_cost']=$full;$r['units_per_batch']=(int)floor($yield/(float)$size['base_value']);$mode=$r['pricing_mode']??'margin';$target=fc_number($r['target']??0);
        if($mode==='margin'){if($target>=100)throw new DomainException('Target margin must be below 100%.');$raw=$full/(1-$target/100);}elseif($mode==='markup')$raw=$full*(1+$target/100);elseif($mode==='profit')$raw=$full+$target;elseif($mode==='manual')$raw=fc_number($r['manual_price']??null,true);else throw new DomainException('Choose a pricing mode.');
        $inc=ceil(($raw*(1+$vat/100)-1e-9)/$round)*$round;$ex=$inc/(1+$vat/100);$r['price_ex']=$ex;$r['price_inc']=$inc;$r['vat_rate']=$vat;$r['actual_margin']=$ex>0?($ex-$full)/$ex*100:null;$r['actual_markup']=$full>0?($ex-$full)/$full*100:null;
    }catch(DomainException $e){$r['issue']=$e->getMessage();$issues[]='Selling size '.($i+1).': '.$e->getMessage();}$sizes[]=$r;}
    $out=['ingredients'=>$ingredients,'production'=>$p,'batches'=>$batches,'selling_sizes'=>$sizes,'totals'=>$totals,'issues'=>array_values(array_unique($issues))];$out['source_token']=hash('sha256',json_encode($out));return $out;
}
function fc_version_token(array $f,array $v):string{return hash('sha256',json_encode([$f,$v]));}
function fc_save(PDO $pdo,array $b):array{
    $h=$b['header']??[];$name=trim((string)($h['formulation_name']??''));if($name===''||strlen($name)>190)throw new DomainException('Enter a formulation name (maximum 190 characters).');
    $date=(string)($h['effective_date']??'');if($date!==''){$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date)throw new DomainException('Invalid effective date.');}
    $approve=($b['approve']??false)===true;$id=(int)($b['id']??0);$request=(string)($b['request_id']??'');if(!preg_match('/^[a-zA-Z0-9-]{16,80}$/',$request))throw new DomainException('Missing save request ID.');$fingerprint=hash('sha256',json_encode($b));$u=lpc_user();
    $pdo->beginTransaction();try{
        $pdo->query("SELECT setting_value FROM cw_settings WHERE setting_key='formulation_vat_rate' FOR UPDATE")->fetch();
        $q=$pdo->prepare("SELECT formulation_id,after_json FROM cw_formulation_audit WHERE JSON_UNQUOTE(JSON_EXTRACT(after_json,'$.request_id'))=? LIMIT 1");$q->execute([$request]);if($prior=$q->fetch()){$a=json_decode($prior['after_json'],true);if($a['fingerprint']!==$fingerprint)throw new DomainException('Request ID already used.');$pdo->commit();return ['ok'=>true,'id'=>(int)$prior['formulation_id'],'message'=>'Saved previously.'];}
        $current=null;if($id){$q=$pdo->prepare('SELECT * FROM cw_formulations WHERE id=? FOR UPDATE');$q->execute([$id]);$current=$q->fetch();if(!$current||!$current['active'])throw new DomainException('Formulation unavailable or archived.');$q=$pdo->prepare('SELECT * FROM cw_formulation_versions WHERE formulation_id=? AND version_no=?');$q->execute([$id,$current['current_version']]);$v=$q->fetch();if(!hash_equals(fc_version_token($current,$v),(string)($b['version_token']??'')))throw new DomainException('This formulation changed elsewhere. Reopen before saving.');}
        $result=fc_calculate($b,fc_sources($pdo,$b));if($approve){if($date==='')throw new DomainException('Effective date is required for approval.');if($result['issues'])throw new DomainException(implode(' ',$result['issues']));if(!hash_equals($result['source_token'],(string)($b['source_token']??'')))throw new DomainException('Costs changed. Refresh and review the calculation before approval.');}
        $code=$current?$current['formulation_code']:'FRM-'.strtoupper(bin2hex(random_bytes(6)));$version=$current?(int)$current['current_version']+1:1;$h['formulation_code']=$code;$h['status_key']=$approve?'active':'draft';$h['vat_rate']=(float)(fc_sources($pdo)['settings']['formulation_vat_rate']??15);$basis=in_array($h['formulation_type']??'', ['weight','volume','count','mixed'],true)?$h['formulation_type']:'weight';
        if($current)$pdo->prepare('UPDATE cw_formulations SET formulation_name=?,category=?,formulation_type=?,status_key=?,current_version=?,effective_date=?,updated_by=?,updated_by_name=? WHERE id=?')->execute([$name,$h['category']??'',$basis,$h['status_key'],$version,$date?:null,$u['id'],$u['name'],$id]);
        else{$pdo->prepare('INSERT INTO cw_formulations(formulation_name,formulation_code,category,formulation_type,status_key,current_version,effective_date,created_by,created_by_name,updated_by,updated_by_name) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$name,$code,$h['category']??'',$basis,$h['status_key'],$version,$date?:null,$u['id'],$u['name'],$u['id'],$u['name']]);$id=(int)$pdo->lastInsertId();}
        $json=function($x){return json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);};
        $pdo->prepare('INSERT INTO cw_formulation_versions(formulation_id,version_no,version_status,effective_date,mode_key,reference_batch_size,reference_batch_unit,expected_yield,yield_unit,loss_percent,vat_rate,header_json,ingredients_json,production_json,batches_json,selling_sizes_json,totals_json,created_by,created_by_name) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$version,$approve?'approved':'draft',$date?:null,($h['mode_key']??'quantity')==='percentage'?'percentage':'quantity',max(0,(float)($h['reference_batch_size']??0)),$h['reference_batch_unit']??'kg',max(0,(float)($h['expected_yield']??0)),$h['yield_unit']??'kg',max(0,(float)($h['loss_percent']??0)),$h['vat_rate'],$json($h),$json($result['ingredients']),$json($result['production']),$json($result['batches']),$json($result['selling_sizes']),$json($result['totals']+['issues'=>$result['issues']]),$u['id'],$u['name']]);
        $pdo->prepare('INSERT INTO cw_formulation_audit(formulation_id,action_key,before_json,after_json,actor_id,actor_name) VALUES(?,?,?,?,?,?)')->execute([$id,$approve?'approved':'draft_saved',$current?$json($current):null,$json(['request_id'=>$request,'fingerprint'=>$fingerprint,'version'=>$version]),$u['id'],$u['name']]);$pdo->commit();return ['ok'=>true,'id'=>$id,'version'=>$version,'message'=>$approve?'Formulation approved.':'Draft saved.'];
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
